        + valClass.getName() + ", received " + value.getClass().getName());
  }
  if (partition < 0 || partition >= partitions) {
    throw new IOException("Illegal partition for " + key + " (" + partition + ")");
  }
}

private void ensureBufferSpace() throws IOException {
  spillLock.lock();
  try {
    if (!spillInProgress) {
      final int kvbidx = 4 * kvindex;
      final int kvbend = 4 * kvend;
      final int bUsed = distanceTo(kvbidx, bufindex);
      final boolean bufsoftlimit = bUsed >= softLimit;
      if ((kvbend + METASIZE) % kvbuffer.length != equator - (equator % METASIZE)) {
        resetSpill();
        bufferRemaining = Math.min(distanceTo(bufindex, kvbidx) - 2 * METASIZE,
            softLimit - bUsed) - METASIZE;
      } else if (bufsoftlimit && kvindex != kvend) {
        startSpill();
        final int avgRec = (int) (mapOutputByteCounter.getCounter() /
            mapOutputRecordCounter.getCounter());
        final int distkvi = distanceTo(bufindex, kvbidx);
        final int newPos = (bufindex + Math.max(2 * METASIZE - 1,
            Math.min(distkvi / 2, distkvi / (METASIZE + avgRec) * METASIZE)))
            % kvbuffer.length;
        setEquator(newPos);
        bufmark = bufindex = newPos;
        final int serBound = 4 * kvend;
        bufferRemaining = Math.min(distanceTo(bufend, newPos),
            Math.min(distanceTo(newPos, serBound), softLimit)) - 2 * METASIZE;
      }
    }
  } finally {
    spillLock.unlock();
  }
}

