  @Override
  public void handle(ContainerAllocatorEvent event) {
    int qSize = eventQueue.size();
    if (qSize != 0 && qSize % 1000 == 0) {
      LOG.info("Size of event-queue in RMContainerAllocator is " + qSize);
    }
    int remCapacity = eventQueue.remainingCapacity();
    if (remCapacity < 1000) {
      LOG.warn("Very low remaining capacity in the event-queue "
          + "of RMContainerAllocator: " + remCapacity);
    }
    try {
      eventQueue.put(event);
    } catch (InterruptedException e) {
      throw new YarnRuntimeException(e);
    }
  }

  @SuppressWarnings({ "unchecked" })
  protected synchronized void handleEvent(ContainerAllocatorEvent event) {
    recalculateReduceSchedule = true;
    switch (event.getType()) {
      case CONTAINER_REQ:
        processContainerReqEvent((ContainerRequestEvent) event);
        break;
      case CONTAINER_DEALLOCATE:
        processContainerDeallocateEvent(event);
        break;
      case CONTAINER_FAILED:
        processContainerFailedEvent((ContainerFailedEvent) event);
        break;
      default:
        LOG.warn("Unhandled event type: " + event.getType());
    }
  }

  private void processContainerReqEvent(ContainerRequestEvent reqEvent) {
    JobId jobId = getJob().getID();
    Resource supportedMaxContainerCapability = getMaxContainerCapability();
    TaskType taskType = reqEvent.getAttemptID().getTaskId().getTaskType();

    if (taskType.equals(TaskType.MAP)) {
      handleMapRequest(reqEvent, jobId, supportedMaxContainerCapability);
    } else {
      handleReduceRequest(reqEvent, jobId, supportedMaxContainerCapability);
    }
  }

  private void handleMapRequest(ContainerRequestEvent reqEvent, JobId jobId,
      Resource supportedMaxContainerCapability) {
    if (mapResourceRequest.equals(Resources.none())) {
      mapResourceRequest = reqEvent.getCapability();
      eventHandler.handle(new JobHistoryEvent(jobId,
          new NormalizedResourceEvent(
              org.apache.hadoop.mapreduce.TaskType.MAP,
              mapResourceRequest.getMemory())));
      LOG.info("mapResourceRequest:" + mapResourceRequest);
      validateResourceCapability(mapResourceRequest, supportedMaxContainerCapability,
          "MAP capability required is more than the supported max container capability in the cluster. Killing the Job. mapResourceRequest: ");
    }
    reqEvent.getCapability().setMemory(mapResourceRequest.getMemory());
    reqEvent.getCapability().setVirtualCores(mapResourceRequest.getVirtualCores());
    scheduledRequests.addMap(reqEvent);
  }

  private void handleReduceRequest(ContainerRequestEvent reqEvent, JobId jobId,
      Resource supportedMaxContainerCapability) {
    if (reduceResourceRequest.equals(Resources.none())) {
      reduceResourceRequest = reqEvent.getCapability();
      eventHandler.handle(new JobHistoryEvent(jobId,
          new NormalizedResourceEvent(
              org.apache.hadoop.mapreduce.TaskType.REDUCE,
              reduceResourceRequest.getMemory())));
      LOG.info("reduceResourceRequest:" + reduceResourceRequest);
      validateResourceCapability(reduceResourceRequest, supportedMaxContainerCapability,
          "REDUCE capability required is more than the supported max container capability in the cluster. Killing the Job. reduceResourceRequest: ");
    }
    reqEvent.getCapability().setMemory(reduceResourceRequest.getMemory());
    reqEvent.getCapability().setVirtualCores(reduceResourceRequest.getVirtualCores());
    if (reqEvent.getEarlierAttemptFailed()) {
      pendingReduces.addFirst(new ContainerRequest(reqEvent, PRIORITY_REDUCE));
    } else {
      pendingReduces.add(new ContainerRequest(reqEvent, PRIORITY_REDUCE));
    }
  }

  private void validateResourceCapability(Resource request, Resource supported,
      String diagPrefix) {
    if (request.getMemory() > supported.getMemory()
        || request.getVirtualCores() > supported.getVirtualCores()) {
      String diagMsg = diagPrefix + request + " maxContainerCapability:" + supported;
      LOG.info(diagMsg);
      eventHandler.handle(new JobDiagnosticsUpdateEvent(getJob().getID(), diagMsg));
      eventHandler.handle(new JobEvent(getJob().getID(), JobEventType.JOB_KILL));
    }
  }

  private void processContainerDeallocateEvent(ContainerAllocatorEvent event) {
    LOG.info("Processing the event " + event.toString());
    TaskAttemptId aId = event.getAttemptID();
    boolean removed = scheduledRequests.remove(aId);
    if (!removed) {
      ContainerId containerId = assignedRequests.get(aId);
      if (containerId != null) {
        removed = true;
        assignedRequests.remove(aId);
        containersReleased++;
        pendingRelease.add(containerId);
        release(containerId);
      }
    }
    if (!removed) {
      LOG.error("Could not deallocate container for task attemptId " + aId);
    }
  }

  private void processContainerFailedEvent(ContainerFailedEvent fEv) {
    String host = getHost(fEv.getContMgrAddress());
    containerFailedOnHost(host);
  }

  private static String getHost(String contMgrAddress) {
    String host = contMgrAddress;
    String[] hostport = host.split(":");
    if (hostport.length == 2) {
      host = hostport[0];
    }
    return host;
  }

