  private boolean hasAccess(RMApp app, HttpServletRequest hsr) {
    UserGroupInformation callerUGI = getCallerUserGroupInformation(hsr, true);
    if (callerUGI == null) {
      return true;
    }
    return rm.getApplicationACLsManager().checkAccess(callerUGI,
        ApplicationAccessType.VIEW_APP, app.getUser(), app.getApplicationId())
        || rm.getQueueACLsManager().checkAccess(callerUGI,
        QueueACL.ADMINISTER_QUEUE, app.getQueue());
  }

  private UserGroupInformation getCallerUserGroupInformation(HttpServletRequest hsr, boolean usePrincipal) {
    String remoteUser = hsr.getRemoteUser();
    if (usePrincipal) {
      Principal princ = hsr.getUserPrincipal();
      remoteUser = princ == null ? null : princ.getName();
    }
    return remoteUser == null ? null : UserGroupInformation.createRemoteUser(remoteUser);
  }

  private boolean isStaticUser(UserGroupInformation callerUGI) {
    String staticUser = conf.get(CommonConfigurationKeys.HADOOP_HTTP_STATIC_USER,
        CommonConfigurationKeys.DEFAULT_HADOOP_HTTP_STATIC_USER);
    return staticUser.equals(callerUGI.getUserName());
  }

  private Set<String> parseQueries(Set<String> queries, boolean isState) {
    Set<String> params = new HashSet<>();
    if (queries == null || queries.isEmpty()) {
      return params;
    }
    for (String query : queries) {
      if (query == null || query.trim().isEmpty()) continue;
      for (String param : query.split(",")) {
        if (param == null || param.trim().isEmpty()) continue;
        String trimmed = param.trim();
        if (isState) {
          try {
            YarnApplicationState.valueOf(StringUtils.toUpperCase(trimmed));
          } catch (RuntimeException e) {
            YarnApplicationState[] stateArray = YarnApplicationState.values();
            String allAppStates = Arrays.toString(stateArray);
            throw new BadRequestException(
                "Invalid application-state " + trimmed + " specified. It should be one of " + allAppStates);
          }
        }
        params.add(StringUtils.toLowerCase(trimmed));
      }
    }
    return params;
  }

  private Map<YarnApplicationState, Map<String, Long>> buildScoreboard(Set<String> states, Set<String> types) {
    Map<YarnApplicationState, Map<String, Long>> scoreboard = new HashMap<>();
    for (String state : states) {
      Map<String, Long> partScoreboard = new HashMap<>();
      scoreboard.put(YarnApplicationState.valueOf(StringUtils.toUpperCase(state)), partScoreboard);
      for (String type : types) {
        partScoreboard.put(type, 0L);
      }
    }
    return scoreboard;
  }

  private void countApp(Map<YarnApplicationState, Map<String, Long>> scoreboard,
      YarnApplicationState state, String type) {
    scoreboard.get(state).put(type, scoreboard.get(state).get(type) + 1L);
  }

  private RMApp getRMAppForAppId(String appId) {
    if (appId == null || appId.isEmpty()) {
      throw new NotFoundException("appId, " + appId + ", is empty or null");
    }
    ApplicationId id;
    try {
      id = ConverterUtils.toApplicationId(recordFactory, appId);
    } catch (NumberFormatException e) {
      throw new NotFoundException("appId is invalid");
    }
    RMApp app = rm.getRMContext().getRMApps().get(id);
    if (app == null) {
      throw new NotFoundException("app with id: " + appId + " not found");
    }
    return app;
  }

