  @GET
  @Path("/apps")
  @Produces({ MediaType.APPLICATION_JSON, MediaType.APPLICATION_XML })
  public AppsInfo getApps(@Context HttpServletRequest hsr,
      @QueryParam("state") String stateQuery,
      @QueryParam("states") Set<String> statesQuery,
      @QueryParam("finalStatus") String finalStatusQuery,
      @QueryParam("user") String userQuery,
      @QueryParam("queue") String queueQuery,
      @QueryParam("limit") String count,
      @QueryParam("startedTimeBegin") String startedBegin,
      @QueryParam("startedTimeEnd") String startedEnd,
      @QueryParam("finishedTimeBegin") String finishBegin,
      @QueryParam("finishedTimeEnd") String finishEnd,
      @QueryParam("applicationTypes") Set<String> applicationTypes,
      @QueryParam("applicationTags") Set<String> applicationTags) {

    init();
    GetApplicationsRequest request = buildGetApplicationsRequest(
        count, startedBegin, startedEnd, finishBegin, finishEnd,
        applicationTypes, applicationTags, queueQuery, userQuery,
        stateQuery, statesQuery);

    List<ApplicationReport> appReports;
    try {
      appReports = rm.getClientRMService()
          .getApplications(request, false).getApplicationList();
    } catch (YarnException e) {
      LOG.error("Unable to retrieve apps from ClientRMService", e);
      throw new YarnRuntimeException("Unable to retrieve apps from ClientRMService", e);
    }

    AppsInfo allApps = new AppsInfo();
    ConcurrentMap<ApplicationId, RMApp> apps = rm.getRMContext().getRMApps();
    for (ApplicationReport report : appReports) {
      RMApp rmapp = apps.get(report.getApplicationId());
      if (rmapp == null) continue;
      if (finalStatusQuery != null && !finalStatusQuery.isEmpty()
          && !rmapp.getFinalApplicationStatus().toString()
              .equalsIgnoreCase(finalStatusQuery)) {
        continue;
      }
      AppInfo app = new AppInfo(rm, rmapp,
          hasAccess(rmapp, hsr), WebAppUtils.getHttpSchemePrefix(conf));
      allApps.add(app);
    }
    return allApps;
  }

  private GetApplicationsRequest buildGetApplicationsRequest(
      String count, String startedBegin, String startedEnd,
      String finishBegin, String finishEnd,
      Set<String> applicationTypes, Set<String> applicationTags,
      String queueQuery, String userQuery,
      String stateQuery, Set<String> statesQuery) {

    GetApplicationsRequest request = GetApplicationsRequest.newInstance();

    long countNum = parseLongIfPresent(count, "limit");
    if (countNum > 0) request.setLimit(countNum);

    long[] startedRange = parseTimeRange(startedBegin, startedEnd, "startedTime");
    if (startedRange != null) request.setStartRange(startedRange[0], startedRange[1]);

    long[] finishedRange = parseTimeRange(finishBegin, finishEnd, "finishedTime");
    if (finishedRange != null) request.setFinishRange(finishedRange[0], finishedRange[1]);

    Set<String> appTypes = parseQueries(applicationTypes, false);
    if (!appTypes.isEmpty()) request.setApplicationTypes(appTypes);

    Set<String> appTags = parseQueries(applicationTags, false);
    if (!appTags.isEmpty()) request.setApplicationTags(appTags);

    Set<String> appStates = parseQueries(statesQuery, true);
    if (stateQuery != null && !stateQuery.isEmpty()) {
      appStates.add(StringUtils.toLowerCase(stateQuery));
    }
    if (!appStates.isEmpty()) request.setApplicationStates(appStates);

    if (queueQuery != null && !queueQuery.isEmpty()) {
      validateQueue(queueQuery);
      request.setQueues(Collections.singleton(queueQuery));
    }

    if (userQuery != null && !userQuery.isEmpty()) {
      request.setUsers(Collections.singleton(userQuery));
    }

    return request;
  }

  private long parseLongIfPresent(String value, String paramName) {
    if (value == null || value.isEmpty()) return 0;
    long parsed = Long.parseLong(value);
    if (parsed <= 0) {
      throw new BadRequestException(paramName + " value must be greater then 0");
    }
    return parsed;
  }

  private long[] parseTimeRange(String begin, String end, String paramName) {
    if ((begin == null || begin.isEmpty()) && (end == null || end.isEmpty())) {
      return null;
    }
    long sBegin = parseLongIfPresent(begin, paramName + "Begin");
    long sEnd = parseLongIfPresent(end, paramName + "End");
    if (sBegin > sEnd) {
      throw new BadRequestException(paramName + "End must be greater than " + paramName + "Begin");
    }
    return new long[]{sBegin, sEnd};
  }

  private void validateQueue(String queueQuery) {
    ResourceScheduler rs = rm.getResourceScheduler();
    if (rs instanceof CapacityScheduler) {
      CapacityScheduler cs = (CapacityScheduler) rs;
      try {
        cs.getQueueInfo(queueQuery, false, false);
      } catch (IOException e) {
        throw new BadRequestException(e.getMessage());
      }
    }
  }

  @GET
  @Path("/appstatistics")
  @Produces({ MediaType.APPLICATION_JSON, MediaType.APPLICATION_XML })
  public ApplicationStatisticsInfo getAppStatistics(
      @Context HttpServletRequest hsr,
      @QueryParam("states") Set<String> stateQueries,
      @QueryParam("applicationTypes") Set<String> typeQueries) {

    init();
    Set<String> states = parseQueries(stateQueries, true);
    Set<String> types = parseQueries(typeQueries, false);
    if (types.isEmpty()) {
      types.add(ANY);
    } else if (types.size() > 1) {
      throw new BadRequestException("# of applicationTypes = " + types.size()
          + ", we temporarily support at most one applicationType");
    }
    if (states.isEmpty()) {
      for (YarnApplicationState state : YarnApplicationState.values()) {
        states.add(StringUtils.toLowerCase(state.toString()));
      }
    }

    Map<YarnApplicationState, Map<String, Long>> scoreboard =
        buildScoreboard(states, types);

    ConcurrentMap<ApplicationId, RMApp> apps = rm.getRMContext().getRMApps();
    for (RMApp rmapp : apps.values()) {
      YarnApplicationState state = rmapp.createApplicationState();
      String type = StringUtils.toLowerCase(rmapp.getApplicationType().trim());
      if (states.contains(StringUtils.toLowerCase(state.toString()))) {
        if (types.contains(ANY)) {
          countApp(scoreboard, state, ANY);
        } else if (types.contains(type)) {
          countApp(scoreboard, state, type);
        }
      }
    }

    ApplicationStatisticsInfo appStatInfo = new ApplicationStatisticsInfo();
    for (Map.Entry<YarnApplicationState, Map<String, Long>> partScoreboard : scoreboard.entrySet()) {
      for (Map.Entry<String, Long> statEntry : partScoreboard.getValue().entrySet()) {
        appStatInfo.add(new StatisticsItemInfo(partScoreboard.getKey(), statEntry.getKey(), statEntry.getValue()));
      }
    }
    return appStatInfo;
  }

