  @Consumes({ MediaType.APPLICATION_JSON, MediaType.APPLICATION_XML })
  public Response updateAppQueue(AppQueue targetQueue,
      @Context HttpServletRequest hsr, @PathParam("appid") String appId)
      throws AuthorizationException, YarnException, InterruptedException,
      IOException {
    init();
    UserGroupInformation callerUGI = getCallerUserGroupInformation(hsr, true);
    if (callerUGI == null) {
      throw new AuthorizationException("Unable to obtain user name, user not authenticated");
    }
    if (UserGroupInformation.isSecurityEnabled() && isStaticUser(callerUGI)) {
      return Response.status(Status.FORBIDDEN).entity("The default static user cannot carry out this operation.").build();
    }
    String userName = callerUGI.getUserName();
    RMApp app = getRMAppForAppId(appId, userName, AuditConstants.KILL_APP_REQUEST);
    if (!app.getQueue().equals(targetQueue.getQueue())) {
      return moveApp(app, callerUGI, targetQueue.getQueue());
    }
    AppQueue ret = new AppQueue();
    ret.setQueue(app.getQueue());
    return Response.status(Status.OK).entity(ret).build();
  }

  protected Response moveApp(RMApp app, UserGroupInformation callerUGI,
      String targetQueue) throws IOException, InterruptedException {
    if (app == null) {
      throw new IllegalArgumentException("app cannot be null");
    }
    String userName = callerUGI.getUserName();
    ApplicationId appid = app.getApplicationId();
    try {
      callerUGI.doAs((PrivilegedExceptionAction<Void>) () -> {
        MoveApplicationAcrossQueuesRequest req =
            MoveApplicationAcrossQueuesRequest.newInstance(appid, targetQueue);
        rm.getClientRMService().moveApplicationAcrossQueues(req);
        return null;
      });
    } catch (UndeclaredThrowableException ue) {
      handleMoveException(ue, app, userName);
    }
    AppQueue ret = new AppQueue();
    ret.setQueue(app.getQueue());
    return Response.status(Status.OK).entity(ret).build();
  }

  private void handleMoveException(UndeclaredThrowableException ue,
      RMApp app, String userName) {
    if (ue.getCause() instanceof YarnException) {
      YarnException ye = (YarnException) ue.getCause();
      if (ye.getCause() instanceof AccessControlException) {
        String appId = app.getApplicationId().toString();
        String msg = "Unauthorized attempt to move appid " + appId
            + " by remote user " + userName;
        throw new AuthorizationException(msg);
      } else if (ye.getMessage().startsWith("App in")
          && ye.getMessage().endsWith("state cannot be moved.")) {
        throw new BadRequestException(ye.getMessage());
      } else {
        throw ue;
      }
    } else {
      throw ue;
    }
  }

  private RMApp getRMAppForAppId(String appId, String userName, String auditEvent) {
    if (appId == null || appId.isEmpty()) {
      throw new NotFoundException("appId, " + appId + ", is empty or null");
    }
    ApplicationId id;
    try {
      id = ConverterUtils.toApplicationId(recordFactory, appId);
    } catch (NumberFormatException e) {
      throw new NotFoundException("appId is invalid");
    }
    if (id == null) {
      throw new NotFoundException("appId is invalid");
    }
    RMApp app = rm.getRMContext().getRMApps().get(id);
    if (app == null) {
      RMAuditLogger.logFailure(userName, auditEvent,
          "UNKNOWN", "RMWebService", "Trying to get state of an absent application " + appId);
      throw new NotFoundException("app with id: " + appId + " not found");
    }
    return app;
  }

