  @GET
  @Path("/scheduler")
  @Produces({ MediaType.APPLICATION_JSON, MediaType.APPLICATION_XML })
  public SchedulerTypeInfo getSchedulerInfo() {
    init();
    ResourceScheduler rs = rm.getResourceScheduler();
    SchedulerInfo sinfo;
    if (rs instanceof CapacityScheduler) {
      CapacityScheduler cs = (CapacityScheduler) rs;
      CSQueue root = cs.getRootQueue();
      sinfo = new CapacitySchedulerInfo(root);
    } else if (rs instanceof FairScheduler) {
      FairScheduler fs = (FairScheduler) rs;
      sinfo = new FairSchedulerInfo(fs);
    } else if (rs instanceof FifoScheduler) {
      sinfo = new FifoSchedulerInfo(this.rm);
    } else {
      throw new NotFoundException("Unknown scheduler configured");
    }
    return new SchedulerTypeInfo(sinfo);
  }

  @GET
  @Path("/nodes")
  @Produces({ MediaType.APPLICATION_JSON, MediaType.APPLICATION_XML })
  public NodesInfo getNodes(@QueryParam("states") String states) {
    init();
    ResourceScheduler sched = this.rm.getResourceScheduler();
    if (sched == null) {
      throw new NotFoundException("Null ResourceScheduler instance");
    }

    EnumSet<NodeState> acceptedStates = parseNodeStates(states);
    Collection<RMNode> rmNodes = RMServerUtils.queryRMNodes(this.rm.getRMContext(),
        acceptedStates);
    NodesInfo nodesInfo = new NodesInfo();
    for (RMNode rmNode : rmNodes) {
      NodeInfo nodeInfo = new NodeInfo(rmNode, sched);
      if (EnumSet.of(NodeState.LOST, NodeState.DECOMMISSIONED, NodeState.REBOOTED)
          .contains(rmNode.getState())) {
        nodeInfo.setNodeHTTPAddress(EMPTY);
      }
      nodesInfo.add(nodeInfo);
    }
    return nodesInfo;
  }

  private EnumSet<NodeState> parseNodeStates(String states) {
    if (states == null) {
      return EnumSet.allOf(NodeState.class);
    }
    EnumSet<NodeState> acceptedStates = EnumSet.noneOf(NodeState.class);
    for (String stateStr : states.split(",")) {
      acceptedStates.add(
          NodeState.valueOf(StringUtils.toUpperCase(stateStr)));
    }
    return acceptedStates;
  }

  @GET
  @Path("/nodes/{nodeId}")
  @Produces({ MediaType.APPLICATION_JSON, MediaType.APPLICATION_XML })
  public NodeInfo getNode(@PathParam("nodeId") String nodeId) {
    init();
    if (nodeId == null || nodeId.isEmpty()) {
      throw new NotFoundException("nodeId, " + nodeId + ", is empty or null");
    }
    ResourceScheduler sched = this.rm.getResourceScheduler();
    if (sched == null) {
      throw new NotFoundException("Null ResourceScheduler instance");
    }
    NodeId nid = ConverterUtils.toNodeId(nodeId);
    RMNode ni = this.rm.getRMContext().getRMNodes().get(nid);
    boolean isInactive = false;
    if (ni == null) {
      ni = this.rm.getRMContext().getInactiveRMNodes().get(nid.getHost());
      if (ni == null) {
        throw new NotFoundException("nodeId, " + nodeId + ", is not found");
      }
      isInactive = true;
    }
    NodeInfo nodeInfo = new NodeInfo(ni, sched);
    if (isInactive) {
      nodeInfo.setNodeHTTPAddress(EMPTY);
    }
    return nodeInfo;
  }

  @GET
  @Path("/apps")
  @Produces({ MediaType.APPLICATION_JSON, MediaType.APPLICATION_XML })
  public AppsInfo getApps(@Context HttpServletRequest hsr,
      @QueryParam("state") String stateQuery,
      @QueryParam("states") Set<String> statesQuery,
      @QueryParam("finalStatus") String finalStatusQuery,
      @QueryParam("user") String userQuery,
      @QueryParam("queue") String queueQuery,
      @QueryParam("limit") String count,
      @QueryParam("startedTimeBegin") String startedBegin,
      @QueryParam("startedTimeEnd") String startedEnd,
      @QueryParam("finishedTimeBegin") String finishBegin,
      @QueryParam("finishedTimeEnd") String finishEnd,
      @QueryParam("applicationTypes") Set<String> applicationTypes,
      @QueryParam("applicationTags") Set<String> applicationTags) {
    init();
    GetApplicationsRequest request = buildGetApplicationsRequest(
        count, startedBegin, startedEnd, finishBegin, finishEnd,
        applicationTypes, applicationTags, statesQuery, stateQuery,
        queueQuery, userQuery);
    List<ApplicationReport> appReports = fetchApplicationReports(request);
    AppsInfo allApps = filterAndBuildApps(appReports, finalStatusQuery, hsr);
    return allApps;
  }

  private GetApplicationsRequest buildGetApplicationsRequest(
      String count, String startedBegin, String startedEnd,
      String finishBegin, String finishEnd,
      Set<String> applicationTypes, Set<String> applicationTags,
      Set<String> statesQuery, String stateQuery,
      String queueQuery, String userQuery) {
    GetApplicationsRequest request = GetApplicationsRequest.newInstance();

    if (count != null && !count.isEmpty()) {
      long countNum = Long.parseLong(count);
      if (countNum <= 0) {
        throw new BadRequestException("limit value must be greater then 0");
      }
      request.setLimit(countNum);
    }

    if (startedBegin != null && !startedBegin.isEmpty()) {
      long sBegin = Long.parseLong(startedBegin);
      if (sBegin < 0) {
        throw new BadRequestException("startedTimeBegin must be greater than 0");
      }
      long sEnd = startedEnd != null && !startedEnd.isEmpty()
          ? Long.parseLong(startedEnd) : Long.MAX_VALUE;
      if (sBegin > sEnd) {
        throw new BadRequestException(
            "startedTimeEnd must be greater than startTimeBegin");
      }
      request.setStartRange(sBegin, sEnd);
    }

    if (finishBegin != null && !finishBegin.isEmpty()) {
      long fBegin = Long.parseLong(finishBegin);
      if (fBegin < 0) {
        throw new BadRequestException("finishTimeBegin must be greater than 0");
      }
      long fEnd = finishEnd != null && !finishEnd.isEmpty()
          ? Long.parseLong(finishEnd) : Long.MAX_VALUE;
      if (fBegin > fEnd) {
        throw new BadRequestException(
            "finishTimeEnd must be greater than finishTimeBegin");
      }
      request.setFinishRange(fBegin, fEnd);
    }

    Set<String> appTypes = parseQueries(applicationTypes, false);
    if (!appTypes.isEmpty()) {
      request.setApplicationTypes(appTypes);
    }

    Set<String> appTags = parseQueries(applicationTags, false);
    if (!appTags.isEmpty()) {
      request.setApplicationTags(appTags);
    }

    Set<String> appStates = parseQueries(statesQuery, true);
    if (stateQuery != null && !stateQuery.isEmpty()) {
      appStates.add(stateQuery);
    }
    if (!appStates.isEmpty()) {
      request.setApplicationStates(appStates);
    }

    if (queueQuery != null && !queueQuery.isEmpty()) {
      validateQueue(queueQuery);
      request.setQueues(new HashSet<>(Arrays.asList(queueQuery)));
    }

    if (userQuery != null && !userQuery.isEmpty()) {
      request.setUsers(new HashSet<>(Arrays.asList(userQuery)));
    }

    return request;
  }

  private void validateQueue(String queueQuery) {
    ResourceScheduler rs = rm.getResourceScheduler();
    if (rs instanceof CapacityScheduler) {
      CapacityScheduler cs = (CapacityScheduler) rs;
      try {
        cs.getQueueInfo(queueQuery, false, false);
      } catch (IOException e) {
        throw new BadRequestException(e.getMessage());
      }
    }
  }

  private List<ApplicationReport> fetchApplicationReports(
      GetApplicationsRequest request) {
    try {
      return rm.getClientRMService()
          .getApplications(request, false).getApplicationList();
