            return rm.getClientRMService().cancelDelegationToken(req);
          }
        });
    } catch (UndeclaredThrowableException ue) {
      if (ue.getCause() instanceof YarnException) {
        if (ue.getCause().getCause() instanceof InvalidToken) {
          throw new BadRequestException(ue.getCause().getCause().getMessage());
        } else if (ue.getCause().getCause() instanceof org.apache.hadoop.security.AccessControlException) {
          return Response.status(Status.FORBIDDEN)
            .entity(ue.getCause().getCause().getMessage()).build();
        }
        LOG.info("Renew delegation token request failed", ue);
        throw ue;
      }
      LOG.info("Renew delegation token request failed", ue);
      throw ue;
    } catch (Exception e) {
      LOG.info("Renew delegation token request failed", e);
      throw e;
    }
    return Response.status(Status.OK).build();
  }

  private Token<RMDelegationTokenIdentifier> extractToken(
      HttpServletRequest request) {
    String encodedToken = request.getHeader(DELEGATION_TOKEN_HEADER);
    if (encodedToken == null) {
      String msg =
          "Header '" + DELEGATION_TOKEN_HEADER
              + "' containing encoded token not found";
      throw new BadRequestException(msg);
    }
    return extractToken(encodedToken);
  }

  private Token<RMDelegationTokenIdentifier> extractToken(String encodedToken) {
    Token<RMDelegationTokenIdentifier> token =
        new Token<RMDelegationTokenIdentifier>();
    try {
      token.decodeFromUrlString(encodedToken);
    } catch (Exception ie) {
      String msg = "Could not decode encoded token";
      throw new BadRequestException(msg);
    }
    return token;
  }

  /**
   * Helper class to build GetApplicationsRequest with a fluent API.
   */
  private static class ApplicationRequestBuilder {
    private final GetApplicationsRequest request;
    private boolean startRangeSet = false;
    private long startRangeBegin;
    private long startRangeEnd = Long.MAX_VALUE;
    private boolean finishRangeSet = false;
    private long finishRangeBegin;
    private long finishRangeEnd = Long.MAX_VALUE;

    ApplicationRequestBuilder() {
      request = GetApplicationsRequest.newInstance();
    }

    void setStartRange(long begin) {
      startRangeBegin = begin;
      startRangeSet = true;
    }

    void setStartRangeEnd(long end) {
      startRangeEnd = end;
      startRangeSet = true;
    }

    void setFinishRange(long begin) {
      finishRangeBegin = begin;
      finishRangeSet = true;
    }

    void setFinishRangeEnd(long end) {
      finishRangeEnd = end;
      finishRangeSet = true;
    }

    void setLimit(long limit) {
      request.setLimit(limit);
    }

    void setApplicationTypes(Set<String> types) {
      request.setApplicationTypes(types);
    }

    void setApplicationTags(Set<String> tags) {
      request.setApplicationTags(tags);
    }

    void setApplicationStates(Set<String> states) {
      request.setApplicationStates(states);
    }

    void setQueues(Set<String> queues) {
      request.setQueues(queues);
    }

    void setUsers(Set<String> users) {
      request.setUsers(users);
    }

    boolean isStartRangeSet() {
      return startRangeSet;
    }

    long getStartRangeBegin() {
      return startRangeBegin;
    }

    long getStartRangeEnd() {
      return startRangeEnd;
    }

    boolean isFinishRangeSet() {
      return finishRangeSet;
    }

    long getFinishRangeBegin() {
      return finishRangeBegin;
    }

    long getFinishRangeEnd() {
      return finishRangeEnd;
    }

    GetApplicationsRequest build() {
      if (startRangeSet) {
        request.setStartRange(startRangeBegin, startRangeEnd);
      }
      if (finishRangeSet) {
        request.setFinishRange(finishRangeBegin, finishRangeEnd);
      }
      return request;
    }
  }

  /**
   * Validates that the specified queue exists in the scheduler.
   */
  private void validateQueueExists(String queue, ResourceScheduler rs) {
    if (rs instanceof CapacityScheduler) {
      CapacityScheduler cs = (CapacityScheduler) rs;
      try {
        cs.getQueueInfo(queue, false, false);
      } catch (IOException e) {
        throw new BadRequestException(e.getMessage());
      }
    }
  }
