  final DatanodeInfo targetDN = target.getDatanodeInfo();
  if (isSameNode(targetDN)) {
    return true;
  }
  if (cluster.isNodeGroupAware() && trySelectSameNodeGroup(targetDN)) {
    return true;
  }
  if (trySelectSameRack(targetDN)) {
    return true;
  }
  return trySelectNonBusy();
}

