  for (StorageGroup loc : block.getLocations()) {
    if (cluster.isOnSameRack(loc.getDatanodeInfo(), targetDN)
        && addTo(loc)) {
      return true;
    }
  }
  return false;
}

/** Try to select any non‑busy proxy */
private boolean trySelectNonBusy() {
  for (StorageGroup loc : block.getLocations()) {
    if (addTo(loc)) {
      return true;
    }
  }
  return false;
}

