private FSEditLogOp readOp(EditLogInputStream in, long[] recentOpcodeOffsets, long numEdits, long expectedTxId, MetaRecoveryContext recovery) throws IOException {
  try {
    FSEditLogOp op = in.readOp();
    if (op == null) return null;
    recentOpcodeOffsets[(int)(numEdits % recentOpcodeOffsets.length)] = in.getPosition();
    if (op.hasTransactionId()) {
      long txId = op.getTransactionId();
      if (txId > expectedTxId) {
        MetaRecoveryContext.editLogLoaderPrompt("There appears to be a gap in the edit log.  We expected txid " + expectedTxId + ", but got txid " + txId + ".", recovery, "ignoring missing transaction IDs");
      } else if (txId < expectedTxId) {
        MetaRecoveryContext.editLogLoaderPrompt("There appears to be an out-of-order edit in the edit log.  We expected txid " + expectedTxId + ", but got txid " + txId + ".", recovery, "skipping the out-of-order edit");
        return null; // skip
      }
    }
    return op;
  } catch (Throwable e) {
    check203UpgradeFailure(in.getVersion(true), e);
    String errorMessage = formatEditLogReplayError(in, recentOpcodeOffsets, expectedTxId);
    FSImage.LOG.error(errorMessage, e);
    if (recovery == null) {
      throw new EditLogInputException(errorMessage, e, numEdits);
    }
    MetaRecoveryContext.editLogLoaderPrompt("We failed to read txId " + expectedTxId, recovery, "skipping the bad section in the log");
    in.resync();
    return null;
  }
}

