private FSEditLogOp readNextOp(EditLogInputStream in, long[] recentOffsets,
      long expectedTxId, MetaRecoveryContext recovery) throws IOException {
    FSEditLogOp op;
    try {
      op = in.readOp();
      if (op == null) return null;
    } catch (Throwable e) {
      check203UpgradeFailure(in.getVersion(true), e);
      String errorMessage = formatEditLogReplayError(in, recentOffsets, expectedTxId);
      FSImage.LOG.error(errorMessage, e);
      if (recovery == null) {
        throw new EditLogInputException(errorMessage, e, 0);
      }
      MetaRecoveryContext.editLogLoaderPrompt(
          "We failed to read txId " + expectedTxId,
          recovery, "skipping the bad section in the log");
      in.resync();
      return readNextOp(in, recentOffsets, expectedTxId, recovery);
    }
    recentOffsets[(int)(numEdits % recentOffsets.length)] = in.getPosition();
    return op;
}
