private void logProgressIfNeeded(FSEditLogOp op, long lastLogTimeRef,
      long expectedStartingTxId, long numTxns) {
    if (!op.hasTransactionId()) return;
    long now = monotonicNow();
    if (now - lastLogTimeRef > REPLAY_TRANSACTION_LOG_INTERVAL) {
      long deltaTxId = lastAppliedTxId - expectedStartingTxId + 1;
      int percent = Math.round((float) deltaTxId / numTxns * 100);
      LOG.info("replaying edit log: " + deltaTxId + "/" + numTxns
          + " transactions completed. (" + percent + "%)");
      lastLogTimeRef = now;
    }
}
