public class FSEditLogLoader {
  static final Log LOG = LogFactory.getLog(FSEditLogLoader.class.getName());
  static final long REPLAY_TRANSACTION_LOG_INTERVAL = 1000; // 1sec

  private final FSNamesystem fsNamesys;
  private long lastAppliedTxId;
  /** Total number of end transactions loaded. */
  private int totalEdits = 0;

  public FSEditLogLoader(FSNamesystem fsNamesys, long lastAppliedTxId) {
    this.fsNamesys = fsNamesys;
    this.lastAppliedTxId = lastAppliedTxId;
  }

  long loadFSEdits(EditLogInputStream edits, long expectedStartingTxId)
      throws IOException {
    return loadFSEdits(edits, expectedStartingTxId, null, null);
  }

  /**
   * Load an edit log, and apply the changes to the in-memory structure
   * This is where we apply edits that we've been writing to disk all
   * along.
   */
  long loadFSEdits(EditLogInputStream edits, long expectedStartingTxId,
      StartupOption startOpt, MetaRecoveryContext recovery) throws IOException {
    StartupProgress prog = NameNode.getStartupProgress();
    Step step = createStartupProgressStep(edits);
    prog.beginStep(Phase.LOADING_EDITS, step);
    fsNamesys.writeLock();
    try {
      long startTime = monotonicNow();
      FSImage.LOG.info("Start loading edits file " + edits.getName());
      long numEdits = loadEditRecords(edits, false, expectedStartingTxId,
          startOpt, recovery);
      FSImage.LOG.info("Edits file " + edits.getName() 
          + " of size " + edits.length() + " edits # " + numEdits 
          + " loaded in " + (monotonicNow()-startTime)/1000 + " seconds");
      return numEdits;
    } finally {
      edits.close();
      fsNamesys.writeUnlock();
      prog.endStep(Phase.LOADING_EDITS, step);
    }
  }

  long loadEditRecords(EditLogInputStream in, boolean closeOnExit,
      long expectedStartingTxId, StartupOption startOpt,
      MetaRecoveryContext recovery) throws IOException {
    FSDirectory fsDir = fsNamesys.dir;

    EnumMap<FSEditLogOpCodes, Holder<Integer>> opCounts =
      new EnumMap<FSEditLogOpCodes, Holder<Integer>>(FSEditLogOpCodes.class);

    if (LOG.isTraceEnabled()) {
      LOG.trace("Acquiring write lock to replay edit log");
    }

    fsNamesys.writeLock();
    fsDir.writeLock();

    long recentOpcodeOffsets[] = new long[4];
    Arrays.fill(recentOpcodeOffsets, -1);

    long expectedTxId = expectedStartingTxId;
    long numEdits = 0;
    long lastTxId = in.getLastTxId();
    long numTxns = (lastTxId - expectedStartingTxId) + 1;
    StartupProgress prog = NameNode.getStartupProgress();
    Step step = createStartupProgressStep(in);
    prog.setTotal(Phase.LOADING_EDITS, step, numTxns);
    Counter counter = prog.getCounter(Phase.LOADING_EDITS, step);
    long lastLogTime = monotonicNow();
    long lastInodeId = fsNamesys.dir.getLastInodeId();

    try {
      while (true) {
        try {
          FSEditLogOp op;
          try {
            op = in.readOp();
            if (op == null) {
              break;
            }
          } catch (Throwable e) {
            // Handle a problem with our input
            check203UpgradeFailure(in.getVersion(true), e);
            String errorMessage =
              formatEditLogReplayError(in, recentOpcodeOffsets, expectedTxId);
            FSImage.LOG.error(errorMessage, e);
            if (recovery == null) {
               // We will only try to skip over problematic opcodes when in
               // recovery mode.
              throw new EditLogInputException(errorMessage, e, numEdits);
            }
            MetaRecoveryContext.editLogLoaderPrompt(
                "We failed to read txId " + expectedTxId,
                recovery, "skipping the bad section in the log");
            in.resync();
            continue;
          }
          recentOpcodeOffsets[(int)(numEdits % recentOpcodeOffsets.length)] =
            in.getPosition();
          if (op.hasTransactionId()) {
            if (op.getTransactionId() > expectedTxId) { 
              MetaRecoveryContext.editLogLoaderPrompt("There appears " +
                  "to be a gap in the edit log.  We expected txid " +
                  expectedTxId + ", but got txid " +
                  op.getTransactionId() + ".", recovery, "ignoring missing " +
                  " transaction IDs");
            } else if (op.getTransactionId() < expectedTxId) { 
              MetaRecoveryContext.editLogLoaderPrompt("There appears " +
                  "to be an out-of-order edit in the edit log.  We " +
                  "expected txid " + expectedTxId + ", but got txid " +
                  op.getTransactionId() + ".", recovery,
                  "skipping the out-of-order edit");
              continue;
            }
          }
          try {
            if (LOG.isTraceEnabled()) {
              LOG.trace("op=" + op + ", startOpt=" + startOpt
                  + ", numEdits=" + numEdits + ", totalEdits=" + totalEdits);
            }
            long inodeId = applyEditLogOp(op, fsDir, startOpt,
                in.getVersion(true), lastInodeId);
            if (lastInodeId < inodeId) {
              lastInodeId = inodeId;
            }
          } catch (RollingUpgradeOp.RollbackException e) {
            throw e;
          } catch (Throwable e) {
            LOG.error("Encountered exception on operation " + op, e);
            if (recovery == null) {
              throw e instanceof IOException? (IOException)e: new IOException(e);
            }

            MetaRecoveryContext.editLogLoaderPrompt("Failed to " +
             "apply edit log operation " + op + ": error " +
             e.getMessage(), recovery, "applying edits");
          }
          // Now that the operation has been successfully decoded and
          // applied, update our bookkeeping.
          incrOpCount(op.opCode, opCounts, step, counter);
          if (op.hasTransactionId()) {
            lastAppliedTxId = op.getTransactionId();
            expectedTxId = lastAppliedTxId + 1;
          } else {
            expectedTxId = lastAppliedTxId = expectedStartingTxId;
          }
          // log progress
          if (op.hasTransactionId()) {
            long now = monotonicNow();
            if (now - lastLogTime > REPLAY_TRANSACTION_LOG_INTERVAL) {
              long deltaTxId = lastAppliedTxId - expectedStartingTxId + 1;
              int percent = Math.round((float) deltaTxId / numTxns * 100);
              LOG.info("replaying edit log: " + deltaTxId + "/" + numTxns
                  + " transactions completed. (" + percent + "%)");
              lastLogTime = now;
            }
          }
          numEdits++;
          totalEdits++;
        } catch (RollingUpgradeOp.RollbackException e) {
          LOG.info("Stopped at OP_START_ROLLING_UPGRADE for rollback.");
          break;
        } catch (MetaRecoveryContext.RequestStopException e) {
          MetaRecoveryContext.LOG.warn("Stopped reading edit log at " +
              in.getPosition() + "/"  + in.length());
          break;
        }
      }
    } finally {
      fsNamesys.dir.resetLastInodeId(lastInodeId);
      if(closeOnExit) {
        in.close();
      }
      fsDir.writeUnlock();
      fsNamesys.writeUnlock();

      if (LOG.isTraceEnabled()) {
        LOG.trace("replaying edit log finished");
      }

      if (FSImage.LOG.isDebugEnabled()) {
        dumpOpCounts(opCounts);
      }
    }
    return numEdits;
  }

  // allocate and update last allocated inode id
  private long getAndUpdateLastInodeId(long inodeIdFromOp, int logVersion,
      long lastInodeId) throws IOException {
    long inodeId = inodeIdFromOp;

    if (inodeId == INodeId.GRANDFATHER_INODE_ID) {
      if (NameNodeLayoutVersion.supports(
          LayoutVersion.Feature.ADD_INODE_ID, logVersion)) {
        throw new IOException("The layout version " + logVersion
            + " supports inodeId but gave bogus inodeId");
      }
      inodeId = fsNamesys.dir.allocateNewInodeId();
    } else {
      // need to reset lastInodeId. fsnamesys gets lastInodeId firstly from
      // fsimage but editlog captures more recent inodeId allocations
      if (inodeId > lastInodeId) {
        fsNamesys.dir.resetLastInodeId(inodeId);
      }
    }
    return inodeId;
  }

  @SuppressWarnings("deprecation")
  private long applyEditLogOp(FSEditLogOp op, FSDirectory fsDir,
      StartupOption startOpt, int logVersion, long lastInodeId) throws IOException {
    long inodeId = INodeId.GRANDFATHER_INODE_ID;
    if (LOG.isTraceEnabled()) {
      LOG.trace("replaying edit log: " + op);
    }
    final boolean toAddRetryCache = fsNamesys.hasRetryCache() && op.hasRpcIds();

    switch (op.opCode) {
    case OP_ADD:
      inodeId = handleAdd((AddCloseOp)op, fsDir, logVersion, lastInodeId, toAddRetryCache);
      break;
    case OP_CLOSE:
      inodeId = handleClose((AddCloseOp)op, fsDir, logVersion, toAddRetryCache);
      break;
    case OP_APPEND:
      inodeId = handleAppend((AppendOp)op, fsDir, logVersion, toAddRetryCache);
      break;
    case OP_UPDATE_BLOCKS:
      inodeId = handleUpdateBlocks((UpdateBlocksOp)op, fsDir, logVersion, toAddRetryCache);
      break;
    case OP_ADD_BLOCK:
      inodeId = handleAddBlock((AddBlockOp)op, fsDir, logVersion);
      break;
    case OP_SET_REPLICATION:
      inodeId = handleSetReplication((SetReplicationOp)op, fsDir, logVersion);
      break;
    case OP_CONCAT_DELETE:
      inodeId = handleConcatDelete((ConcatDeleteOp)op, fsDir, logVersion, toAddRetryCache);
      break;
    case OP_RENAME_OLD:
      inodeId = handleRenameOld((RenameOldOp)op, fsDir, logVersion, toAddRetryCache);
      break;
    case OP_DELETE:
      inodeId = handleDelete((DeleteOp)op, fsDir, logVersion, toAddRetryCache);
      break;
    case OP_MKDIR:
      inodeId = handleMkdir((MkdirOp)op, fsDir, logVersion, lastInodeId);
      break;
    case OP_SET_GENSTAMP_V1:
      inodeId = handleSetGenstampV1((SetGenstampV1Op)op);
      break;
    case OP_SET_PERMISSIONS:
      inodeId = handleSetPermissions((SetPermissionsOp)op, fsDir, logVersion);
      break;
    case OP_SET_OWNER:
      inodeId = handleSetOwner((SetOwnerOp)op, fsDir, logVersion);
      break;
    case OP_SET_NS_QUOTA:
      inodeId = handleSetNSQuota((SetNSQuotaOp)op, fsDir, logVersion);
      break;
    case OP_CLEAR_NS_QUOTA:
      inodeId = handleClearNSQuota((ClearNSQuotaOp)op, fsDir, logVersion);
      break;
    case OP_SET_QUOTA:
      inodeId = handleSetQuota((SetQuotaOp)op, fsDir, logVersion);
      break;
    case OP_SET_QUOTA_BY_STORAGETYPE:
      inodeId = handleSetQuotaByStorageType((FSEditLogOp.SetQuotaByStorageTypeOp)op, fsDir, logVersion);
      break;
    case OP_TIMES:
      inodeId = handleTimes((TimesOp)op, fsDir, logVersion);
      break;
    case OP_SYMLINK:
      inodeId = handleSymlink((SymlinkOp)op, fsDir, logVersion, toAddRetryCache);
      break;
    case OP_RENAME:
      inodeId = handleRename((RenameOp)op, fsDir, logVersion, toAddRetryCache);
      break;
    case OP_GET_DELEGATION_TOKEN:
      inodeId = handleGetDelegationToken((GetDelegationTokenOp)op);
      break;
    case OP_RENEW_DELEGATION_TOKEN:
      inodeId = handleRenewDelegationToken((RenewDelegationTokenOp)op);
      break;
    case OP_CANCEL_DELEGATION_TOKEN:
      inodeId = handleCancelDelegationToken((CancelDelegationTokenOp)op);
      break;
    case OP_UPDATE_MASTER_KEY:
      inodeId = handleUpdateMasterKey((UpdateMasterKeyOp)op);
      break;
    case OP_REASSIGN_LEASE:
      inodeId = handleReassignLease((ReassignLeaseOp)op, fsDir, logVersion);
      break;
    case OP_START_LOG_SEGMENT:
    case OP_END_LOG_SEGMENT:
      inodeId = handleLogSegment();
      break;
    case OP_CREATE_SNAPSHOT:
      inodeId = handleCreateSnapshot((CreateSnapshotOp)op, fsDir, logVersion, toAddRetryCache);
      break;
    case OP_DELETE_SNAPSHOT:
      inodeId = handleDeleteSnapshot((DeleteSnapshotOp)op, fsDir, logVersion, toAddRetryCache);
      break;
    case OP_RENAME_SNAPSHOT:
      inodeId = handleRenameSnapshot((RenameSnapshotOp)op, fsDir, logVersion, toAddRetryCache);
      break;
    case OP_ALLOW_SNAPSHOT:
      inodeId = handleAllowSnapshot((AllowSnapshotOp)op, fsDir, logVersion);
      break;
    case OP_DISALLOW_SNAPSHOT:
      inodeId = handleDisallowSnapshot((DisallowSnapshotOp)op, fsDir, logVersion);
      break;
    case OP_SET_GENSTAMP_V2:
      inodeId = handleSetGenstampV2((SetGenstampV2Op)op);
      break;
    case OP_ALLOCATE_BLOCK_ID:
      inodeId = handleAllocateBlockId((AllocateBlockIdOp)op);
      break;
    case OP_ROLLING_UPGRADE_START:
      inodeId = handleRollingUpgradeStart(startOpt, op, logVersion);
      break;
    case OP_ROLLING_UPGRADE_FINALIZE:
      inodeId = handleRollingUpgradeFinalize(op, logVersion);
      break;
    case OP_ADD_CACHE_DIRECTIVE:
      inodeId = handleAddCacheDirective((AddCacheDirectiveInfoOp)op, toAddRetryCache);
      break;
    case OP_MODIFY_CACHE_DIRECTIVE:
      inodeId = handleModifyCacheDirective((ModifyCacheDirectiveInfoOp)op, toAddRetryCache);
      break;
    case OP_REMOVE_CACHE_DIRECTIVE:
      inodeId = handleRemoveCacheDirective((RemoveCacheDirectiveInfoOp)op, toAddRetryCache);
      break;
    case OP_ADD_CACHE_POOL:
      inodeId = handleAddCachePool((AddCachePoolOp)op, toAddRetryCache);
      break;
    case OP_MODIFY_CACHE_POOL:
      inodeId = handleModifyCachePool((ModifyCachePoolOp)op, toAddRetryCache);
      break;
    case OP_REMOVE_CACHE_POOL:
      inodeId = handleRemoveCachePool((RemoveCachePoolOp)op, toAddRetryCache);
      break;
    case OP_SET_ACL:
      inodeId = handleSetAcl((SetAclOp)op);
      break;
    case OP_SET_XATTR:
      inodeId = handleSetXAttr((SetXAttrOp)op, toAddRetryCache);
      break;
    case OP_REMOVE_XATTR:
      inodeId = handleRemoveXAttr((RemoveXAttrOp)op, toAddRetryCache);
      break;
    case OP_TRUNCATE:
      inodeId = handleTruncate((TruncateOp)op);
      break;
    case OP_SET_STORAGE_POLICY:
      inodeId = handleSetStoragePolicy((SetStoragePolicyOp)op, fsDir, logVersion);
      break;
    default:
      throw new IOException("Invalid operation read " + op.opCode);
    }
    return inodeId;
  }

  private long handleAdd(AddCloseOp op, FSDirectory fsDir, int logVersion,
      long lastInodeId, boolean toAddRetryCache) throws IOException {
    final String path =
        renameReservedPathsOnUpgrade(op.path, logVersion);
    if (FSNamesystem.LOG.isDebugEnabled()) {
      FSNamesystem.LOG.debug(op.opCode + ": " + path +
          " numblocks : " + op.blocks.length +
          " clientHolder " + op.clientName +
          " clientMachine " + op.clientMachine);
    }
    INodesInPath iip = fsDir.getINodesInPath(path, true);
    INodeFile oldFile = INodeFile.valueOf(iip.getLastINode(), path, true);
    if (oldFile != null && op.overwrite) {
      FSDirDeleteOp.deleteForEditLog(fsDir, path, op.mtime);
      iip = INodesInPath.replace(iip, iip.length() - 1, null);
      oldFile = null;
    }
    INodeFile newFile = oldFile;
    if (oldFile == null) {
      final short replication = fsNamesys.getBlockManager()
          .adjustReplication(op.replication);
      assert op.blocks.length == 0;
      long inodeId = getAndUpdateLastInodeId(op.inodeId, logVersion, lastInodeId);
      newFile = fsDir.addFileForEditLog(inodeId, iip.getExistingINodes(),
          iip.getLastLocalName(),
          op.permissions,
          op.aclEntries,
          op.xAttrs, replication,
          op.mtime, op.atime,
          op.blockSize, true,
          op.clientName,
          op.clientMachine,
          op.storagePolicyId);
      iip = INodesInPath.replace(iip, iip.length() - 1, newFile);
      fsNamesys.leaseManager.addLease(op.clientName, path);
      if (toAddRetryCache) {
        HdfsFileStatus stat = FSDirStatAndListingOp.createFileStatus(
            fsNamesys.dir, path, HdfsFileStatus.EMPTY_NAME, newFile,
            BlockStoragePolicySuite.ID_UNSPECIFIED, Snapshot.CURRENT_STATE_ID,
            false, iip);
        fsNamesys.addCacheEntryWithPayload(op.rpcClientId,
            op.rpcCallId, stat);
      }
    } else {
      if (!oldFile.isUnderConstruction()) {
        LocatedBlock lb = fsNamesys.prepareFileForAppend(path, iip,
            op.clientName, op.clientMachine, false, false,
            false);
        if (toAddRetryCache) {
          HdfsFileStatus stat = FSDirStatAndListingOp.createFileStatus(
              fsNamesys.dir, path,
              HdfsFileStatus.EMPTY_NAME, newFile,
              BlockStoragePolicySuite.ID_UNSPECIFIED,
              Snapshot.CURRENT_STATE_ID, false, iip);
          fsNamesys.addCacheEntryWithPayload(op.rpcClientId,
              op.rpcCallId, new LastBlockWithStatus(lb, stat));
        }
      }
    }
    newFile.setAccessTime(op.atime, Snapshot.CURRENT_STATE_ID);
    newFile.setModificationTime(op.mtime, Snapshot.CURRENT_STATE_ID);
    updateBlocks(fsDir, op, iip, newFile);
    return newFile.getId();
  }

  private long handleClose(AddCloseOp op, FSDirectory fsDir, int logVersion,
      boolean toAddRetryCache) throws IOException {
    final String path =
        renameReservedPathsOnUpgrade(op.path, logVersion);
    if (FSNamesystem.LOG.isDebugEnabled()) {
      FSNamesystem.LOG.debug(op.opCode + ": " + path +
          " numblocks : " + op.blocks.length +
          " clientHolder " + op.clientName +
          " clientMachine " + op.clientMachine);
    }
    INodesInPath iip = fsDir.getINodesInPath(path, true);
    INodeFile file = INodeFile.valueOf(iip.getLastINode(), path);
    file.setAccessTime(op.atime, Snapshot.CURRENT_STATE_ID);
    file.setModificationTime(op.mtime, Snapshot.CURRENT_STATE_ID);
    updateBlocks(fsDir, op, iip, file);
    if (!file.isUnderConstruction() &&
        logVersion <= LayoutVersion.BUGFIX_HDFS_2991_VERSION) {
      throw new IOException(
          "File is not under construction: " + path);
    }
    if (file.isUnderConstruction()) {
      fsNamesys.leaseManager.removeLeaseWithPrefixPath(path);
      file.toCompleteFile(file.getModificationTime());
    }
    return INodeId.GRANDFATHER_INODE_ID;
  }

  private long handleAppend(AppendOp op, FSDirectory fsDir, int logVersion,
      boolean toAddRetryCache) throws IOException {
    final String path = renameReservedPathsOnUpgrade(op.path, logVersion);
    if (FSNamesystem.LOG.isDebugEnabled()) {
      FSNamesystem.LOG.debug(op.opCode + ": " + path +
          " clientName " + op.clientName +
          " clientMachine " + op.clientMachine +
          " newBlock " + op.newBlock);
    }
    INodesInPath iip = fsDir.getINodesInPath4Write(path);
    INodeFile file = INodeFile.valueOf(iip.getLastINode(), path);
    if (!file.isUnderConstruction()) {
      LocatedBlock lb = fsNamesys.prepareFileForAppend(path, iip,
          op.clientName, op.clientMachine, op.newBlock,
          false, false);
      if (toAddRetryCache) {
        HdfsFileStatus stat = FSDirStatAndListingOp.createFileStatus(
            fsNamesys.dir, path, HdfsFileStatus.EMPTY_NAME, file,
            BlockStoragePolicySuite.ID_UNSPECIFIED,
            Snapshot.CURRENT_STATE_ID, false, iip);
        fsNamesys.addCacheEntryWithPayload(op.rpcClientId,
            op.rpcCallId, new LastBlockWithStatus(lb, stat));
      }
    }
    return INodeId.GRANDFATHER_INODE_ID;
  }

  private long handleUpdateBlocks(UpdateBlocksOp op, FSDirectory fsDir,
      int logVersion, boolean toAddRetryCache) throws IOException {
