  private long handleDeleteSnapshot(DeleteSnapshotOp op, FSDirectory fsDir,
      int logVersion, boolean toAddRetryCache) throws IOException {
    BlocksMapUpdateInfo collectedBlocks = new BlocksMapUpdateInfo();
    List<INode> removedINodes = new ChunkedArrayList<INode>();
    final String snapshotRoot =
        renameReservedPathsOnUpgrade(op.snapshotRoot,
            logVersion);
    INodesInPath iip = fsDir.getINodesInPath4Write(snapshotRoot);
    fsNamesys.getSnapshotManager().deleteSnapshot(
        iip, op.snapshotName,
        collectedBlocks, removedINodes);
    fsNamesys.removeBlocksAndUpdateSafemodeTotal(collectedBlocks);
    collectedBlocks.clear();
    fsNamesys.dir.removeFromInodeMap(removedINodes);
    removedINodes.clear();
    if (toAddRetryCache) {
      fsNamesys.addCacheEntry(op.rpcClientId,
          op.rpcCallId);
    }
    return INodeId.GRANDFATHER_INODE_ID;
  }

  private long handleRenameSnapshot(RenameSnapshotOp op, FSDirectory fsDir,
      int logVersion, boolean toAddRetryCache) throws IOException {
    final String snapshotRoot =
        renameReservedPathsOnUpgrade(op.snapshotRoot,
            logVersion);
    INodesInPath iip = fsDir.getINodesInPath4Write(snapshotRoot);
    fsNamesys.getSnapshotManager().renameSnapshot(iip,
        snapshotRoot, op.snapshotOldName,
        op.snapshotNewName);
    if (toAddRetryCache) {
      fsNamesys.addCacheEntry(op.rpcClientId,
